formulas.expression:
VALUE(
LEFT(
  RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Contrast Reading - Full Field Mode:", {!OutputFormatFetched}) - LEN("Contrast Reading - Full Field Mode:")),
  FIND("<br>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("Contrast Reading - Full Field Mode:", {!OutputFormatFetched}) - LEN("Contrast Reading - Full Field Mode:"))) - 1
)
)

